function formatContentToParagraphs(content) {
  if (!content || content.trim().length === 0) {
    return '<p><em>This section is pending analysis and will be completed in the next report iteration.</em></p>';
  }

  return content
    .split(/\n\s*\n/)
    .filter(para => para.trim().length > 10)
    .map(para => para.trim().replace(/\n/g, ' '))
    .map(para => `<p>${para.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')}</p>`)
