const firstSectionData = $node['Prepare Database Data'].json;
const taskId = firstSectionData.task_id;

const finalData = {
  task_id: taskId,
  company_name: approvalData.company_name || 'UNKNOWN_COMPANY',
  methodology_content: approvalData.generated_content || 'Business Model section generation failed',
  status: 'Section Complete - Business Model & Unit Economics',
  created_at: new Date().toISOString()
};

return { json: finalData };

const approverResponse = $input.first().json.response;
const checkerProcessingData = $node['Checker Processing2'].json;

let approverData;
try {
  const jsonMatch = approverResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    approverData = JSON.parse(jsonMatch[0]);
  } else {
    approverData = { approved: true, feedback: "Section approved" };
  }
} catch (error) {
  approverData = { approved: true, feedback: "Section approved" };
}

return {
  json: { ...checkerProcessingData, approver_approved: approverData.approved, approver_feedback: approverData.feedback }
};

const checkerResponse = $input.first().json.response;
const formatOutputData = $node['Format Output2'].json;

let checkerData;
try {
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerData = JSON.parse(jsonMatch[0]);
  } else {
    checkerData = { approved: true, feedback: "Content acceptable", score: 7 };
  }
} catch (error) {
  checkerData = { approved: true, feedback: "Content acceptable", score: 7 };
}

return {
  json: { ...formatOutputData, checker_approved: checkerData.approved, checker_feedback: checkerData.feedback, checker_score: checkerData.score }
};

const report = $input.first().json.response || '';
const dbData = $node['Save ALL Data to Database'].json;

const cleanReport = report
  .replace(/\{\{[^}]*\}\}/g, '')
  .replace(/\$json\.[\w.]+/g, '')
  .replace(/\$node\[[^\]]+\]\.[\w.\[\]]+/g, '')
  .replace(/\[date\]/gi, new Date().toLocaleDateString('en-US'))
  .replace(/\[company name\]/gi, dbData.company_name)
  .trim();

return {
  json: {
    company_name: dbData.company_name,
    generated_content: cleanReport,
    content: dbData.content,
    file_name: dbData.file_name,
    company_id: dbData.company_id,
    section_type: 'business_model_unit_economics'
  }
};

